inline ::flatbuffers::Offset<ASNObservation> CreateASNObservation(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    uint32_t INDEX = 0,
    ::flatbuffers::Offset<::flatbuffers::String> RECORD_TYPE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> TIME = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SENSOR = 0,
    ::flatbuffers::Offset<::flatbuffers::String> TRACK_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<ASNMeasurement>>> MEASUREMENTS = 0,
    uint8_t DEGREES_OF_FREEDOM = 0,
    double GATE = 0.0,
    asnAssociationOutcome OUTCOME = asnAssociationOutcome::Unspecified,
    asnUncorrelatedReason REASON = asnUncorrelatedReason::Unspecified,
    bool AMBIGUOUS = false,
    bool ASSIGNMENT_CONFLICT = false,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<ASNCandidate>>> CANDIDATES = 0,
    int32_t ASSIGNED_CANDIDATE = -1,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> SENSOR_POSITION_GCRF_KM = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> SENSOR_VELOCITY_GCRF_KM_S = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> LINE_OF_SIGHT_GCRF = 0) {
  ASNObservationBuilder builder_(_fbb);
  builder_.add_GATE(GATE);
  builder_.add_LINE_OF_SIGHT_GCRF(LINE_OF_SIGHT_GCRF);
  builder_.add_SENSOR_VELOCITY_GCRF_KM_S(SENSOR_VELOCITY_GCRF_KM_S);
  builder_.add_SENSOR_POSITION_GCRF_KM(SENSOR_POSITION_GCRF_KM);
  builder_.add_ASSIGNED_CANDIDATE(ASSIGNED_CANDIDATE);
  builder_.add_CANDIDATES(CANDIDATES);
  builder_.add_MEASUREMENTS(MEASUREMENTS);
  builder_.add_TRACK_ID(TRACK_ID);
  builder_.add_SENSOR(SENSOR);
  builder_.add_TIME(TIME);
  builder_.add_ID(ID);
  builder_.add_RECORD_TYPE(RECORD_TYPE);
  builder_.add_INDEX(INDEX);
  builder_.add_ASSIGNMENT_CONFLICT(ASSIGNMENT_CONFLICT);
  builder_.add_AMBIGUOUS(AMBIGUOUS);
  builder_.add_REASON(REASON);
  builder_.add_OUTCOME(OUTCOME);
  builder_.add_DEGREES_OF_FREEDOM(DEGREES_OF_FREEDOM);
  return builder_.Finish();
}

